-- 딜링거래 맵핑 : 송금-외환딜링 맵핑(RBI 요구, 기존 요청). XP73/RT11/RT13/RT21 하단 공통 탭. 1딜 다송금/1송금 다딜 허용.
CREATE TABLE TB_FX_DEAL_LINK (
  REMIT_REF_NO             VARCHAR2(16) NOT NULL,
  DEAL_SEQ                 NUMBER(3) NOT NULL,
  DEAL_TYPE                VARCHAR2(4) NOT NULL,
  DEAL_DT                  DATE NOT NULL,
  DEAL_REF_NO              VARCHAR2(16) NOT NULL,
  MANUAL_YN                VARCHAR2(1),
  FX_RATE                  NUMBER(15,6) NOT NULL,
  CUR_INR_AMT              NUMBER(18,2) NOT NULL,
  CUR_FCY_AMT              NUMBER(18,2) NOT NULL,
  TOT_INR_AMT              NUMBER(18,2),
  TOT_FCY_AMT              NUMBER(18,2),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_DEAL_LINK PRIMARY KEY (REMIT_REF_NO, DEAL_SEQ)
);
COMMENT ON TABLE TB_FX_DEAL_LINK IS '딜링거래 맵핑';
COMMENT ON COLUMN TB_FX_DEAL_LINK.REMIT_REF_NO IS '송금참조번호';
COMMENT ON COLUMN TB_FX_DEAL_LINK.DEAL_SEQ IS '순번';
COMMENT ON COLUMN TB_FX_DEAL_LINK.DEAL_TYPE IS '딜 유형 - SPOT/TOM/CASH/FWD';
COMMENT ON COLUMN TB_FX_DEAL_LINK.DEAL_DT IS '거래일';
COMMENT ON COLUMN TB_FX_DEAL_LINK.DEAL_REF_NO IS 'GBS MM Ref - 조회불가 시 수기입력(MANUAL_YN=Y)';
COMMENT ON COLUMN TB_FX_DEAL_LINK.MANUAL_YN IS '수기입력여부';
COMMENT ON COLUMN TB_FX_DEAL_LINK.FX_RATE IS '적용환율';
COMMENT ON COLUMN TB_FX_DEAL_LINK.CUR_INR_AMT IS '당해사용 INR';
COMMENT ON COLUMN TB_FX_DEAL_LINK.CUR_FCY_AMT IS '당해사용 FCY';
COMMENT ON COLUMN TB_FX_DEAL_LINK.TOT_INR_AMT IS '딜 전체 INR - 딜 전체금액≠송금액인 경우';
COMMENT ON COLUMN TB_FX_DEAL_LINK.TOT_FCY_AMT IS '딜 전체 FCY';
COMMENT ON COLUMN TB_FX_DEAL_LINK.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_DEAL_LINK.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_DEAL_LINK.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_DEAL_LINK.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_DEAL_LINK.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- LRS 거래 : 개인 LRS 송금 상세. CIMS 일일보고 원천.
CREATE TABLE TB_LRS_TXN (
  REMIT_REF_NO             VARCHAR2(16) NOT NULL,
  PAN_NO                   VARCHAR2(10) NOT NULL,
  FY                       VARCHAR2(7) NOT NULL,
  LRS_CAT                  VARCHAR2(5) NOT NULL,
  USD_EQV_AMT              NUMBER(18,2) NOT NULL,
  DECL_OTHER_BANK_USD      NUMBER(18,2) NOT NULL,
  CUM_USD_BEFORE           NUMBER(18,2) NOT NULL,
  CUM_USD_AFTER            NUMBER(18,2) NOT NULL,
  TCS_BASE_INR             NUMBER(18,2),
  TCS_RATE                 NUMBER(5,2),
  TCS_AMT                  NUMBER(18,2),
  EDU_LOAN_YN              VARCHAR2(1),
  LOAN_SANCTION_REF        VARCHAR2(30),
  MINOR_YN                 VARCHAR2(1),
  CIMS_RPT_DT              DATE,
  CIMS_RPT_STS             VARCHAR2(4),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_LRS_TXN PRIMARY KEY (REMIT_REF_NO)
);
COMMENT ON TABLE TB_LRS_TXN IS 'LRS 거래';
COMMENT ON COLUMN TB_LRS_TXN.REMIT_REF_NO IS '송금참조번호';
COMMENT ON COLUMN TB_LRS_TXN.PAN_NO IS 'PAN - PAN 미보유 시 LRS 불가';
COMMENT ON COLUMN TB_LRS_TXN.FY IS '회계연도 - 예: 2026-27';
COMMENT ON COLUMN TB_LRS_TXN.LRS_CAT IS 'LRS 목적분류 - CODE:LRS_CAT';
COMMENT ON COLUMN TB_LRS_TXN.USD_EQV_AMT IS 'USD 환산액';
COMMENT ON COLUMN TB_LRS_TXN.DECL_OTHER_BANK_USD IS '타행 기송금 신고액 - Form A2 고객 자기신고. 미신고 0';
COMMENT ON COLUMN TB_LRS_TXN.CUM_USD_BEFORE IS '직전 FY 누적(당행+신고)';
COMMENT ON COLUMN TB_LRS_TXN.CUM_USD_AFTER IS '송금 후 FY 누적 - ≤ LRS_LIMIT_USD';
COMMENT ON COLUMN TB_LRS_TXN.TCS_BASE_INR IS 'TCS 과세표준 - FY 누적 INR - 기준금액 초과분';
COMMENT ON COLUMN TB_LRS_TXN.TCS_RATE IS 'TCS 세율';
COMMENT ON COLUMN TB_LRS_TXN.TCS_AMT IS 'TCS 금액';
COMMENT ON COLUMN TB_LRS_TXN.EDU_LOAN_YN IS '교육대출 재원여부';
COMMENT ON COLUMN TB_LRS_TXN.LOAN_SANCTION_REF IS '대출약정번호';
COMMENT ON COLUMN TB_LRS_TXN.MINOR_YN IS '미성년여부';
COMMENT ON COLUMN TB_LRS_TXN.CIMS_RPT_DT IS 'CIMS 보고일';
COMMENT ON COLUMN TB_LRS_TXN.CIMS_RPT_STS IS 'CIMS 보고상태 - CODE:IF_STATUS';
COMMENT ON COLUMN TB_LRS_TXN.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_LRS_TXN.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_LRS_TXN.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_LRS_TXN.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_LRS_TXN.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_LRS_TXN_1 ON TB_LRS_TXN (PAN_NO,FY);

-- LRS FY 누적 : PAN×FY 누적 집계. 송금 승인 시 행잠금(SELECT FOR UPDATE)으로 동시성 제어.
CREATE TABLE TB_LRS_FY_SUM (
  PAN_NO                   VARCHAR2(10) NOT NULL,
  FY                       VARCHAR2(7) NOT NULL,
  CUM_USD_AMT              NUMBER(18,2) NOT NULL,
  CUM_INR_AMT              NUMBER(18,2) NOT NULL,
  CUM_TCS_AMT              NUMBER(18,2) NOT NULL,
  TXN_CNT                  NUMBER(6) NOT NULL,
  LAST_REMIT_DT            DATE,
  CONSTRAINT PK_LRS_FY_SUM PRIMARY KEY (PAN_NO, FY)
);
COMMENT ON TABLE TB_LRS_FY_SUM IS 'LRS FY 누적';
COMMENT ON COLUMN TB_LRS_FY_SUM.PAN_NO IS 'PAN';
COMMENT ON COLUMN TB_LRS_FY_SUM.FY IS '회계연도';
COMMENT ON COLUMN TB_LRS_FY_SUM.CUM_USD_AMT IS '누적 USD';
COMMENT ON COLUMN TB_LRS_FY_SUM.CUM_INR_AMT IS '누적 INR(TCS 기준)';
COMMENT ON COLUMN TB_LRS_FY_SUM.CUM_TCS_AMT IS '누적 TCS';
COMMENT ON COLUMN TB_LRS_FY_SUM.TXN_CNT IS '건수';
COMMENT ON COLUMN TB_LRS_FY_SUM.LAST_REMIT_DT IS '최종송금일';

-- 인보이스 : RT73 Invoice 탭. 한도관리는 인보이스 Total Amount 기준. 분할송금 시 Consumed/Balance 자동 갱신.
CREATE TABLE TB_TRD_INVOICE (
  INV_MGMT_NO              VARCHAR2(16) NOT NULL,
  IE_TYPE                  VARCHAR2(1) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  IEC_NO                   VARCHAR2(10),
  INV_CATEGORY             VARCHAR2(10) NOT NULL,
  INV_NO                   VARCHAR2(35) NOT NULL,
  INV_DT                   DATE NOT NULL,
  INV_VALID_TO_DT          DATE,
  CCY                      VARCHAR2(3) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  IGST_RATE                NUMBER(5,2),
  IGST_AMT                 NUMBER(18,2),
  TOTAL_AMT                NUMBER(18,2) NOT NULL,
  CONSUMED_AMT             NUMBER(18,2) NOT NULL,
  BALANCE_AMT              NUMBER(18,2) NOT NULL,
  INCOTERMS                VARCHAR2(3),
  MODE_OF_SHIP             VARCHAR2(1),
  VESSEL_NAME              VARCHAR2(20),
  VOYAGE_NO                VARCHAR2(20),
  SHIPPING_DT              DATE,
  EST_SHIP_DT              DATE,
  TRANSPORT_DOC_NO         VARCHAR2(35),
  TRANSPORT_DOC_DT         DATE,
  PORT_OF_SHIPMENT         VARCHAR2(35),
  COUNTRY_ORIGIN           VARCHAR2(2),
  COUNTRY_CONSIGN          VARCHAR2(2),
  PORT_DISCHARGE           VARCHAR2(35),
  PORT_CODE                VARCHAR2(6),
  PLACE_DEST               VARCHAR2(35),
  HS_CODE                  VARCHAR2(8),
  CAPITAL_GOODS_YN         VARCHAR2(1),
  BENE_NAME                VARCHAR2(140),
  BENE_CTRY                VARCHAR2(2),
  LC_YN                    VARCHAR2(1),
  LC_NO                    VARCHAR2(16),
  PROJECTED_TURNOVER       NUMBER(18,2),
  STATUS                   VARCHAR2(2) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TRD_INVOICE PRIMARY KEY (INV_MGMT_NO)
);
COMMENT ON TABLE TB_TRD_INVOICE IS '인보이스';
COMMENT ON COLUMN TB_TRD_INVOICE.INV_MGMT_NO IS '인보이스 관리번호';
COMMENT ON COLUMN TB_TRD_INVOICE.IE_TYPE IS '수출입구분 - I수입/E수출';
COMMENT ON COLUMN TB_TRD_INVOICE.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_TRD_INVOICE.IEC_NO IS 'IEC - 인도 당행고객만 필수(선택값 유지-기존 요청)';
COMMENT ON COLUMN TB_TRD_INVOICE.INV_CATEGORY IS '인보이스 구분 - CODE:INV_CATEGORY';
COMMENT ON COLUMN TB_TRD_INVOICE.INV_NO IS 'Invoice No - CUST_NO+INV_NO+INV_DT 유니크(중복송금 방지)';
COMMENT ON COLUMN TB_TRD_INVOICE.INV_DT IS 'Invoice 발행일';
COMMENT ON COLUMN TB_TRD_INVOICE.INV_VALID_TO_DT IS 'Invoice 유효기간 - Proforma 필수. 미입력 시 INV_DT+INV_PROFORMA_VALID_DAYS';
COMMENT ON COLUMN TB_TRD_INVOICE.CCY IS '통화';
COMMENT ON COLUMN TB_TRD_INVOICE.AMT IS '세전금액';
COMMENT ON COLUMN TB_TRD_INVOICE.IGST_RATE IS 'IGST 세율 - 선택값(기존 요청: GST 선택)';
COMMENT ON COLUMN TB_TRD_INVOICE.IGST_AMT IS 'IGST 세액';
COMMENT ON COLUMN TB_TRD_INVOICE.TOTAL_AMT IS '인보이스 총액 - = AMT + IGST_AMT (한도기준)';
COMMENT ON COLUMN TB_TRD_INVOICE.CONSUMED_AMT IS '사용금액 - Σ 송금배분액(TB_TRD_PAY_ALLOC)';
COMMENT ON COLUMN TB_TRD_INVOICE.BALANCE_AMT IS '잔액 - = TOTAL - CONSUMED, 음수 불가';
COMMENT ON COLUMN TB_TRD_INVOICE.INCOTERMS IS 'Incoterms 2020';
COMMENT ON COLUMN TB_TRD_INVOICE.MODE_OF_SHIP IS '운송수단 - 1Land/2Ship/3Air/4Combined';
COMMENT ON COLUMN TB_TRD_INVOICE.VESSEL_NAME IS '선박명(항공편) - 영숫자 20자';
COMMENT ON COLUMN TB_TRD_INVOICE.VOYAGE_NO IS '항차번호';
COMMENT ON COLUMN TB_TRD_INVOICE.SHIPPING_DT IS '선적일(Shipping Date) - 미래일자 허용. 미래일자면 Packing List 생략 가능(기존 요청)';
COMMENT ON COLUMN TB_TRD_INVOICE.EST_SHIP_DT IS '선적예정일';
COMMENT ON COLUMN TB_TRD_INVOICE.TRANSPORT_DOC_NO IS '운송서류번호(B/L, AWB)';
COMMENT ON COLUMN TB_TRD_INVOICE.TRANSPORT_DOC_DT IS '운송서류일자 - 수입결제기한 기산일';
COMMENT ON COLUMN TB_TRD_INVOICE.PORT_OF_SHIPMENT IS '선적항';
COMMENT ON COLUMN TB_TRD_INVOICE.COUNTRY_ORIGIN IS '원산지';
COMMENT ON COLUMN TB_TRD_INVOICE.COUNTRY_CONSIGN IS '위탁국가 - 원산지와 다른 경우 입력. 입력 시 보고용 Country=위탁국';
COMMENT ON COLUMN TB_TRD_INVOICE.PORT_DISCHARGE IS '도착항';
COMMENT ON COLUMN TB_TRD_INVOICE.PORT_CODE IS '도착항 코드 - ICEGATE Port Code (예 INNSA1)';
COMMENT ON COLUMN TB_TRD_INVOICE.PLACE_DEST IS '최종도착지';
COMMENT ON COLUMN TB_TRD_INVOICE.HS_CODE IS 'HS Code - ITC-HS 8자리';
COMMENT ON COLUMN TB_TRD_INVOICE.CAPITAL_GOODS_YN IS '자본재여부 - 선수금 수입기한 36개월 적용';
COMMENT ON COLUMN TB_TRD_INVOICE.BENE_NAME IS '상대방명';
COMMENT ON COLUMN TB_TRD_INVOICE.BENE_CTRY IS '상대방 국가';
COMMENT ON COLUMN TB_TRD_INVOICE.LC_YN IS 'L/C 여부';
COMMENT ON COLUMN TB_TRD_INVOICE.LC_NO IS 'L/C No';
COMMENT ON COLUMN TB_TRD_INVOICE.PROJECTED_TURNOVER IS '예상 거래액 - TBML 모니터링 참고';
COMMENT ON COLUMN TB_TRD_INVOICE.STATUS IS '상태 - 10정상/20완결/90취소';
COMMENT ON COLUMN TB_TRD_INVOICE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_TRD_INVOICE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_TRD_INVOICE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_TRD_INVOICE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_TRD_INVOICE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_TRD_INVOICE_1 ON TB_TRD_INVOICE (CUST_NO,INV_NO,INV_DT);

-- 인보이스 품목(Packing List) : 
CREATE TABLE TB_TRD_INVOICE_ITEM (
  INV_MGMT_NO              VARCHAR2(16) NOT NULL,
