COMMENT ON COLUMN TB_FX_CONV_LEG.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_CONV_LEG.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 미지급금(타발 보류) 원장 : 비계좌 수취인·지시대기·KYC대기 타발을 Remittance Payable(미지급금) GL에 보류. 통화별 잔액 관리.
CREATE TABLE TB_FX_SUSPENSE (
  SUSP_NO                  VARCHAR2(16) NOT NULL,
  REMIT_REF_NO             VARCHAR2(16) NOT NULL,
  GL_CODE                  VARCHAR2(8) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  PARK_AMT                 NUMBER(18,2) NOT NULL,
  BALANCE_AMT              NUMBER(18,2) NOT NULL,
  SUSP_RSN                 VARCHAR2(6) NOT NULL,
  PARK_DT                  DATE NOT NULL,
  DUE_DT                   DATE NOT NULL,
  BENE_NAME                VARCHAR2(140) NOT NULL,
  BENE_ID_TYPE             VARCHAR2(6),
  BENE_ID_NO               VARCHAR2(30),
  SUSP_STS                 VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_SUSPENSE PRIMARY KEY (SUSP_NO)
);
COMMENT ON TABLE TB_FX_SUSPENSE IS '미지급금(타발 보류) 원장';
COMMENT ON COLUMN TB_FX_SUSPENSE.SUSP_NO IS '보류번호';
COMMENT ON COLUMN TB_FX_SUSPENSE.REMIT_REF_NO IS '송금참조번호';
COMMENT ON COLUMN TB_FX_SUSPENSE.GL_CODE IS '미지급금 계정 - 통화별 Remittance Payable GL(신규 채번)';
COMMENT ON COLUMN TB_FX_SUSPENSE.CCY IS '통화 - 외화 보류 또는 INR(환전 후 지급대기)';
COMMENT ON COLUMN TB_FX_SUSPENSE.PARK_AMT IS '보류금액';
COMMENT ON COLUMN TB_FX_SUSPENSE.BALANCE_AMT IS '잔액 - = PARK - Σ환전/지급/반환';
COMMENT ON COLUMN TB_FX_SUSPENSE.SUSP_RSN IS '보류사유 - CODE:SUSP_RSN';
COMMENT ON COLUMN TB_FX_SUSPENSE.PARK_DT IS '보류일';
COMMENT ON COLUMN TB_FX_SUSPENSE.DUE_DT IS '처리기한 - PARK_DT + SUSP_MAX_DAYS(영업일)';
COMMENT ON COLUMN TB_FX_SUSPENSE.BENE_NAME IS '수취인';
COMMENT ON COLUMN TB_FX_SUSPENSE.BENE_ID_TYPE IS '수취인 식별 - PAN/CIN/여권 - 비계좌 KYC';
COMMENT ON COLUMN TB_FX_SUSPENSE.BENE_ID_NO IS '식별번호';
COMMENT ON COLUMN TB_FX_SUSPENSE.SUSP_STS IS '상태 - OPEN/PART/CLSD/RTND(반환)';
COMMENT ON COLUMN TB_FX_SUSPENSE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_SUSPENSE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_SUSPENSE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_SUSPENSE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_SUSPENSE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_SUSPENSE_1 ON TB_FX_SUSPENSE (SUSP_STS,DUE_DT);

-- 국내 INR 지급(NEFT/RTGS) : 타발·FDI·에스크로 지급금을 타행 계좌로 NEFT/RTGS 이체. UTR로 추적, 반송 시 미지급금 재보류.
CREATE TABLE TB_DOM_PAYOUT (
  PAYOUT_ID                NUMBER(12) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  RAIL                     VARCHAR2(4) NOT NULL,
  BENE_NAME                VARCHAR2(140) NOT NULL,
  BENE_IFSC                VARCHAR2(11) NOT NULL,
  BENE_ACCT                VARCHAR2(34) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  REMARKS                  VARCHAR2(140),
  UTR                      VARCHAR2(22),
  SENT_TS                  TIMESTAMP,
  PAYOUT_STS               VARCHAR2(4) NOT NULL,
  RTN_RSN                  VARCHAR2(100),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_DOM_PAYOUT PRIMARY KEY (PAYOUT_ID)
);
COMMENT ON TABLE TB_DOM_PAYOUT IS '국내 INR 지급(NEFT/RTGS)';
COMMENT ON COLUMN TB_DOM_PAYOUT.PAYOUT_ID IS '지급ID';
COMMENT ON COLUMN TB_DOM_PAYOUT.SRC_TABLE IS '원천 - TB_FX_CONV_LEG / TB_FDI_ESCROW_TXN / TB_FX_SUSPENSE';
COMMENT ON COLUMN TB_DOM_PAYOUT.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_DOM_PAYOUT.RAIL IS '이체망 - NEFT/RTGS (RTGS_MIN_INR 미만 RTGS 불가)';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_NAME IS '수취인명';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_IFSC IS 'IFSC - ^[A-Z]{4}0[A-Z0-9]{6}$';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_ACCT IS '수취계좌';
COMMENT ON COLUMN TB_DOM_PAYOUT.AMT IS '금액(INR)';
COMMENT ON COLUMN TB_DOM_PAYOUT.REMARKS IS '이체 메시지 - FDI: FDI_REF_NO·투자자명 기재';
COMMENT ON COLUMN TB_DOM_PAYOUT.UTR IS 'UTR - SFMS 응답';
COMMENT ON COLUMN TB_DOM_PAYOUT.SENT_TS IS '송신일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.PAYOUT_STS IS '상태 - NEW/SENT/CRDT(입금확인)/RTRN(반송)/FAIL';
COMMENT ON COLUMN TB_DOM_PAYOUT.RTN_RSN IS '반송사유 - 반송 시 TB_FX_SUSPENSE(RTN) 재생성';
COMMENT ON COLUMN TB_DOM_PAYOUT.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_DOM_PAYOUT.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_DOM_PAYOUT.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_DOM_PAYOUT_1 ON TB_DOM_PAYOUT (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_DOM_PAYOUT_2 ON TB_DOM_PAYOUT (UTR);

-- FDI 에스크로 계좌 : FDI 관련 에스크로(지분양수도·이연대가·공개매수·인수대금). 무이자, 약정 조건 충족 시 지급/반환.
CREATE TABLE TB_FDI_ESCROW (
  ESCROW_ACCT_NO           VARCHAR2(16) NOT NULL,
  ESCROW_PURP              VARCHAR2(9) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  NR_PARTY_NAME            VARCHAR2(140) NOT NULL,
  NR_PARTY_CTRY            VARCHAR2(2) NOT NULL,
  R_PARTY_CUST_NO          VARCHAR2(8),
  INVESTEE_CIN             VARCHAR2(21) NOT NULL,
  AGREEMENT_REF            VARCHAR2(30) NOT NULL,
  AGREEMENT_DT             DATE NOT NULL,
  TOTAL_CONSIDERATION      NUMBER(18,2),
  ESCROW_LIMIT             NUMBER(18,2) NOT NULL,
  BALANCE_AMT              NUMBER(18,2) NOT NULL,
  EXPIRY_DT                DATE NOT NULL,
  RELEASE_COND             VARCHAR2(500) NOT NULL,
  ESCROW_STS               VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FDI_ESCROW PRIMARY KEY (ESCROW_ACCT_NO)
);
COMMENT ON TABLE TB_FDI_ESCROW IS 'FDI 에스크로 계좌';
COMMENT ON COLUMN TB_FDI_ESCROW.ESCROW_ACCT_NO IS '에스크로 계좌';
COMMENT ON COLUMN TB_FDI_ESCROW.ESCROW_PURP IS '목적 - CODE:ESCROW_PURP';
COMMENT ON COLUMN TB_FDI_ESCROW.CCY IS '통화 - INR 또는 외화';
COMMENT ON COLUMN TB_FDI_ESCROW.NR_PARTY_NAME IS '비거주자 당사자';
COMMENT ON COLUMN TB_FDI_ESCROW.NR_PARTY_CTRY IS '국가 - 인접국이면 정부승인 확인';
COMMENT ON COLUMN TB_FDI_ESCROW.R_PARTY_CUST_NO IS '거주자 당사자';
COMMENT ON COLUMN TB_FDI_ESCROW.INVESTEE_CIN IS '대상회사 CIN';
COMMENT ON COLUMN TB_FDI_ESCROW.AGREEMENT_REF IS '에스크로 약정번호';
COMMENT ON COLUMN TB_FDI_ESCROW.AGREEMENT_DT IS '약정일';
COMMENT ON COLUMN TB_FDI_ESCROW.TOTAL_CONSIDERATION IS '총 거래대가 - 이연대가 비율 검증용';
COMMENT ON COLUMN TB_FDI_ESCROW.ESCROW_LIMIT IS '예치한도 - DEFER: 총대가×25% 이내';
COMMENT ON COLUMN TB_FDI_ESCROW.BALANCE_AMT IS '잔액';
COMMENT ON COLUMN TB_FDI_ESCROW.EXPIRY_DT IS '만기 - DEFER: 약정일+18개월 이내';
COMMENT ON COLUMN TB_FDI_ESCROW.RELEASE_COND IS '지급조건 - 약정 요약(결의·인가·클로징)';
COMMENT ON COLUMN TB_FDI_ESCROW.ESCROW_STS IS '상태 - OPEN/PART/CLSD/RFND';
COMMENT ON COLUMN TB_FDI_ESCROW.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FDI_ESCROW.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FDI_ESCROW.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FDI_ESCROW.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FDI_ESCROW.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- FDI 에스크로 거래 : 예치(타발)·지급(거주자 NEFT/RTGS 또는 계좌)·반환(당발) 거래.
CREATE TABLE TB_FDI_ESCROW_TXN (
  ESCROW_ACCT_NO           VARCHAR2(16) NOT NULL,
  TXN_SEQ                  NUMBER(6) NOT NULL,
  TXN_TYPE                 VARCHAR2(4) NOT NULL,
  TXN_DT                   DATE NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  REMIT_REF_NO             VARCHAR2(16),
  PAYOUT_ID                NUMBER(12),
  RELEASE_EVIDENCE         VARCHAR2(200),
  FCTRS_DUE_DT             DATE,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FDI_ESCROW_TXN PRIMARY KEY (ESCROW_ACCT_NO, TXN_SEQ)
);
COMMENT ON TABLE TB_FDI_ESCROW_TXN IS 'FDI 에스크로 거래';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.ESCROW_ACCT_NO IS '에스크로 계좌';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_SEQ IS '순번';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_TYPE IS '유형 - DEPO예치/RLSE지급/RFND반환';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_DT IS '거래일';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.AMT IS '금액';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REMIT_REF_NO IS '연결 송금 - DEPO=타발, RFND=당발(Product 07)';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.PAYOUT_ID IS '국내지급 - RLSE를 타행 지급 시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.RELEASE_EVIDENCE IS '지급근거 - 양측 공동지시서/클로징 증빙';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.FCTRS_DUE_DT IS 'FC-TRS 신고기한 - 대금 지급일+60일';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 비거주자 NRO 송금 FY 누적 : NRO 잔액(자산매각·기타) 해외송금 FY USD 1M 한도. 경상소득은 별도 집계.
CREATE TABLE TB_NR_REPAT_SUM (
  CUST_NO                  VARCHAR2(8) NOT NULL,
  FY                       VARCHAR2(7) NOT NULL,
  CUM_USD_CAPITAL          NUMBER(18,2) NOT NULL,
  CUM_USD_CURRENT          NUMBER(18,2) NOT NULL,
  TXN_CNT                  NUMBER(6) NOT NULL,
  CONSTRAINT PK_NR_REPAT_SUM PRIMARY KEY (CUST_NO, FY)
);
COMMENT ON TABLE TB_NR_REPAT_SUM IS '비거주자 NRO 송금 FY 누적';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_NR_REPAT_SUM.FY IS '회계연도';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUM_USD_CAPITAL IS '자산·잔액 송금 누적(USD) - ≤ NRO_REPAT_LIMIT_USD';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUM_USD_CURRENT IS '경상소득 송금 누적(USD) - 한도 외, 세후 증빙';
COMMENT ON COLUMN TB_NR_REPAT_SUM.TXN_CNT IS '건수';

-- 환전 거래 : 송금과 분리된 환전 원장: 계좌간·외화간·외화현찰·지점 자기계정. GST(32(2))와 딜 맵핑 포함.
CREATE TABLE TB_FX_EXCHANGE (
  FX_REF_NO                VARCHAR2(16) NOT NULL,
  FX_TYPE                  VARCHAR2(8) NOT NULL,
  CUST_NO                  VARCHAR2(8),
  TRX_DT                   DATE NOT NULL,
  SELL_CCY                 VARCHAR2(3) NOT NULL,
  SELL_AMT                 NUMBER(18,2) NOT NULL,
  SELL_ACCT_NO             VARCHAR2(16),
  BUY_CCY                  VARCHAR2(3) NOT NULL,
  BUY_AMT                  NUMBER(18,2) NOT NULL,
  BUY_ACCT_NO              VARCHAR2(16),
  RATE                     NUMBER(15,6) NOT NULL,
  RATE_SRC                 VARCHAR2(4) NOT NULL,
  DEAL_REF_NO              VARCHAR2(16),
  RBI_REF_RATE             NUMBER(15,6),
  INR_EQV_AMT              NUMBER(18,2) NOT NULL,
  PURPOSE_CODE             VARCHAR2(5),
  PAN_SNAP                 VARCHAR2(10),
  PASSPORT_NO              VARCHAR2(20),
  CDF_NO                   VARCHAR2(20),
  ENCASH_CERT_YN           VARCHAR2(1),
  FX_STS                   VARCHAR2(2) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_EXCHANGE PRIMARY KEY (FX_REF_NO)
);
COMMENT ON TABLE TB_FX_EXCHANGE IS '환전 거래';
COMMENT ON COLUMN TB_FX_EXCHANGE.FX_REF_NO IS '환전 참조번호';
COMMENT ON COLUMN TB_FX_EXCHANGE.FX_TYPE IS '환전유형 - CODE:FX_TYPE';
COMMENT ON COLUMN TB_FX_EXCHANGE.CUST_NO IS '고객번호 - BRANCH 유형은 NULL(내부)';
COMMENT ON COLUMN TB_FX_EXCHANGE.TRX_DT IS '거래일';
COMMENT ON COLUMN TB_FX_EXCHANGE.SELL_CCY IS '고객 지급 통화';
COMMENT ON COLUMN TB_FX_EXCHANGE.SELL_AMT IS '고객 지급 금액';
COMMENT ON COLUMN TB_FX_EXCHANGE.SELL_ACCT_NO IS '출금계좌 - 현찰이면 NULL';
COMMENT ON COLUMN TB_FX_EXCHANGE.BUY_CCY IS '고객 수령 통화 - SELL_CCY와 달라야 함';
COMMENT ON COLUMN TB_FX_EXCHANGE.BUY_AMT IS '고객 수령 금액';
COMMENT ON COLUMN TB_FX_EXCHANGE.BUY_ACCT_NO IS '입금계좌 - INR→EEFC 입금 불가(R-FX-02)';
COMMENT ON COLUMN TB_FX_EXCHANGE.RATE IS '적용환율';
COMMENT ON COLUMN TB_FX_EXCHANGE.RATE_SRC IS '환율출처 - CARD고시/DEAL딜/CASH현찰';
COMMENT ON COLUMN TB_FX_EXCHANGE.DEAL_REF_NO IS '딜 Ref - USD 환산 ≥ FX_DEAL_REQ_USD 또는 BRANCH면 필수';
COMMENT ON COLUMN TB_FX_EXCHANGE.RBI_REF_RATE IS 'RBI 기준환율 - GST 32(2)(a)·외화간 과세표준 산정';
COMMENT ON COLUMN TB_FX_EXCHANGE.INR_EQV_AMT IS 'INR 환산(과세표준 기준)';
COMMENT ON COLUMN TB_FX_EXCHANGE.PURPOSE_CODE IS '목적 - 현찰판매(여행)는 LRS Purpose';
COMMENT ON COLUMN TB_FX_EXCHANGE.PAN_SNAP IS 'PAN - 현찰판매·고액매입 필수';
COMMENT ON COLUMN TB_FX_EXCHANGE.PASSPORT_NO IS '여권번호 - 비계좌·외국인 현찰매입';
COMMENT ON COLUMN TB_FX_EXCHANGE.CDF_NO IS 'CDF 번호 - 현찰매입 기준 초과 시';
COMMENT ON COLUMN TB_FX_EXCHANGE.ENCASH_CERT_YN IS 'Encashment Certificate 발급 - 현찰·TT 매입 시 고객 요청';
COMMENT ON COLUMN TB_FX_EXCHANGE.FX_STS IS '상태 - 10등록/20승인/40완료/90취소';
COMMENT ON COLUMN TB_FX_EXCHANGE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_EXCHANGE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_EXCHANGE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_EXCHANGE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_EXCHANGE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_EXCHANGE_1 ON TB_FX_EXCHANGE (CUST_NO,TRX_DT);

-- 고시환율(Rate Card) : 통화별 TT/현찰 매입·매도율. 시간대별 회차 관리, 자금팀 승인 후 게시.
CREATE TABLE TB_FX_RATE_CARD (
