-- 본지점 기준환율·금리 : 통화간 기준환율+스프레드, 통화별 기준금리+스프레드. 유효기간 이력.
CREATE TABLE TB_IO_RATE (
  RATE_KIND                VARCHAR2(3) NOT NULL,
  CCY_KEY                  VARCHAR2(7) NOT NULL,
  EFF_FROM_DT              DATE NOT NULL,
  EFF_TO_DT                DATE NOT NULL,
