COMMENT ON COLUMN TB_HOLIDAY.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_HOLIDAY.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 휴일 차이 조정 : 본점 고객결제일과 지점 지급일 차이에 따른 이자를 건별 산출 → 흡수 또는 본지점 정산.
CREATE TABLE TB_IO_FLOAT_ADJ (
