COMMENT ON COLUMN TB_IO_FLOAT_ADJ.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 확인서·증명서 발급이력 : FIRC(FM-FDI-01)·당발확인서(FM-OUT-01)·타발확인서(FM-IN-01) 발급/재발급/정정 이력. 원본은 원천 1건당 1회.
CREATE TABLE TB_FX_ADVICE_ISSUE (
  ISSUE_NO                 VARCHAR2(30) NOT NULL,
