  ISSUE_RSN                VARCHAR2(200),
  DELIVERY                 VARCHAR2(4) NOT NULL,
  VERIFY_CODE              VARCHAR2(16) NOT NULL,
  SNAPSHOT_JSON            CLOB NOT NULL,
  DMS_KEY                  VARCHAR2(64),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_ADVICE_ISSUE PRIMARY KEY (ISSUE_NO)
);
COMMENT ON TABLE TB_FX_ADVICE_ISSUE IS '확인서·증명서 발급이력';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_NO IS '발급번호 - 서식약어/지점/FY/일련 (예: FIRC/NOI/2026-27/000041)';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.FORM_ID IS '서식ID - FM-FDI-01 / FM-OUT-01 / FM-IN-01';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_TABLE IS '원천테이블 - TB_FDI_INFLOW / TB_FX_REMIT_MST';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_KEY IS '원천키 - FDI_REF_NO 또는 REMIT_REF_NO';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_TYPE IS '발급구분 - ORG원본/DUP재발급/AMD정정/CXL취소';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ORG_ISSUE_NO IS '원본 발급번호 - DUP/AMD/CXL 시 필수';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_SEQ IS '발급차수 - 원본=1, 재발급마다 +1';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_DT IS '발급일';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_RSN IS '재발급/정정 사유';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DELIVERY IS '전달방식 - PRNT창구출력/MAIL/INET인터넷뱅킹';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.VERIFY_CODE IS '진위확인코드 - HMAC(발급번호+금액+일자) 앞 16자리, QR 표시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SNAPSHOT_JSON IS '발급내용 스냅샷 - 발급 시점 표기값 전체 - 재발급은 이 값으로 동일 재현';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DMS_KEY IS 'PDF 보관키';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_ADVICE_ISSUE_1 ON TB_FX_ADVICE_ISSUE (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_FX_ADVICE_ISSUE_2 ON TB_FX_ADVICE_ISSUE (CUST_NO,ISSUE_DT);

